import test from 'node:test';
import assert from 'node:assert/strict';
import zlib from 'node:zlib';
import { randomBytes } from 'node:crypto';

import {
  HEAPNUM_INLINE_MAX,
  SETTERS,
  extractEmbeddedSources,
  findGameObjectSetters,
  judgeSetters,
  parseBytecodeDump,
} from '../../scripts/checkBundleSetters.mjs';

// N-234's release check (scripts/checkBundleSetters.mjs) reads V8's bytecode of GameObject's setters in a built bundle.
// These pin its reading: d8's --print-bytecode format, the setters told apart by source position, the embedded worker
// sources found in raw and gzip-embedded bundles.

// d8 16 --no-lazy --no-enable-lazy-source-positions --print-bytecode, a setter whose one-caller helper terser wrote in
// as a function called on the spot (E-469).
const DUMP = `[generated bytecode for function: setAlpha (0x01690101e3ed <SharedFunctionInfo setAlpha>)]
Bytecode length: 23
Parameter count 2
Register count 2
Frame size 16
  145 S> 0x501000260 @    0 : 17 ff 02 01       LdaImmutableContextSlot <context>, [2], [1]
         0x501000264 @    4 : d7                Star0
  156 E> 0x501000269 @    9 : 3e f9 f8 00       SetKeyedProperty r0, r1, FBV[0]
  180 S> 0x50100026d @   13 : 8f 00 00 01       CreateClosure [0:0x01690101e509 <SharedFunctionInfo>], FBV[0], #1
  180 E> 0x501000272 @   18 : 6f f9 02 02       CallUndefinedReceiver1 r0, <this>, FBV[2]
  186 S> 0x501000276 @   22 : bb                Return
Constant pool (size = 1)
Handler Table (size = 0)
Source Position Table (size = 13)
[generated bytecode for function: set x (0x01690101e3bd <SharedFunctionInfo set x>)]
Bytecode length: 24
Parameter count 2
Register count 2
Frame size 16
   98 S> 0x501000284 @    0 : 17 ff 02 01       LdaImmutableContextSlot <context>, [2], [1]
  120 E> 0x501000296 @   18 : 6f f9 02 02       CallUndefinedReceiver1 r0, <this>, FBV[2]
         0x50100029a @   22 : 0e                LdaUndefined
  126 S> 0x50100029b @   23 : bb                Return
Constant pool (size = 0)
`;

test('parseBytecodeDump reads each function: name, length, positions, closures', () => {
  const fns = parseBytecodeDump(DUMP);
  assert.deepEqual(fns, [
    { name: 'setAlpha', length: 23, minPos: 145, maxPos: 186, closures: 1 },
    { name: 'set x', length: 24, minPos: 98, maxPos: 126, closures: 0 },
  ]);
});

/** A minified worker chunk: GameObject's setters, and another class's set x before it. */
function chunkSource() {
  const members = SETTERS.map((n, k) => (n.startsWith('set ') ? `${n}(e){Q[${k}]=e,f(this)}` : `${n}(e){return Q[0]=e,f(this)}`));
  return `(self.c=self.c||[]).push([[1],{5:(e,t,i)=>{var Q=new Float32Array(2);function f(e){return e}` +
    `class Point{set x(e){this._x=e}}class GameObject{constructor(){this.index=0}${members.join('')}}}}]);`;
}

test('findGameObjectSetters finds each setter of class GameObject alone', async () => {
  const code = chunkSource();
  const ranges = await findGameObjectSetters(code);
  assert.deepEqual([...ranges.keys()].sort(), [...SETTERS].sort());
  const [setX] = ranges.get('set x');
  assert.equal(code.slice(setX.start, setX.end), 'set x(e){Q[0]=e,f(this)}');
});

test('judgeSetters matches functions by range and fails a long setter or a closure', async () => {
  const ranges = await findGameObjectSetters(chunkSource());
  const fns = [{ name: 'set x', length: 99, minPos: 0, maxPos: 5, closures: 0 }]; // Point's, before GameObject
  for (const [name, [r]] of ranges) {
    const length = name === 'set vy' ? HEAPNUM_INLINE_MAX + 1 : 20;
    fns.push({ name, length, minPos: r.start + 1, maxPos: r.end - 1, closures: name === 'setScale' ? 1 : 0 });
  }
  const rows = judgeSetters(ranges, fns);
  const bad = rows.filter((r) => !r.ok).map((r) => [r.name, r.why]);
  assert.deepEqual(bad, [
    ['set vy', `over ${HEAPNUM_INLINE_MAX} bytes`],
    ['setScale', 'makes 1 closure a call'],
  ]);
  assert.equal(rows.find((r) => r.name === 'set x').length, 20);
});

test('judgeSetters fails a setter it cannot find', async () => {
  const ranges = await findGameObjectSetters(chunkSource());
  ranges.delete('setVelocity');
  const rows = judgeSetters(ranges, []);
  assert.equal(rows.find((r) => r.name === 'setVelocity').why, 'not found in class GameObject');
  assert.ok(rows.every((r) => !r.ok));
});

test('extractEmbeddedSources returns raw and gzip-embedded worker sources', async () => {
  const worker = 'class GameObject{}' + ' '.repeat(30000);
  const noise = randomBytes(30000).toString('hex');
  const common = `var common=${JSON.stringify(noise)};`; // gzip+base64 still past the 20 000 chars the check reads
  const gz = zlib.gzipSync(Buffer.from(common)).toString('base64');
  const bundle = `const w=Object.freeze({logicWorker:${JSON.stringify(worker)}});let c=${JSON.stringify(gz)};export{w,c};`;
  const sources = await extractEmbeddedSources(bundle);
  assert.equal(sources.length, 2);
  assert.equal(sources[0].label, 'logicWorker');
  assert.equal(sources[0].text, worker);
  assert.equal(sources[1].text, common);
});
